int
fcb_getnext_nolock(struct fcb *fcb, struct fcb_entry *loc)
{
	int rc;

	if (loc->fe_sector == NULL) {
		/* Find the first one we have in flash. */
		loc->fe_sector = fcb->f_oldest;
		loc->fe_elem_off = 0U; /* Signal to start from beginning of oldest sector */
	}

	while (true) {
		if (loc->fe_elem_off == 0U) {
			/* If offset is zero, we serve the first entry from the sector. */
			loc->fe_elem_off = fcb_len_in_flash(fcb, sizeof(struct fcb_disk_area));
			rc = fcb_elem_info(fcb, loc);
		} else {
			rc = fcb_getnext_in_sector(fcb, loc);
		}

		if (rc == 0) {
			return 0; /* Found a valid entry */
		} else if (rc == -EBADMSG) {
			/* Continue loop to skip bad entry.
			 * If fcb_elem_info returned -EBADMSG, loc->fe_elem_off
			 * is at the start of the bad entry. fcb_getnext_in_sector
			 * will be called in the next iteration (if loc->fe_elem_off != 0)
			 * to advance it and skip bad entries.
			 * If loc->fe_elem_off was 0 and fcb_elem_info returned -EBADMSG,
			 * the next iteration will call fcb_getnext_in_sector to skip it.
			 */
			continue;
		} else { /* rc is -ENOTSUP or other error, meaning end of current sector */
			if (loc->fe_sector == fcb->f_active.fe_sector) {
				return -ENOTSUP; /* End of FCB */
			}
			loc->fe_sector = fcb_getnext_sector(fcb, loc->fe_sector);
			loc->fe_elem_off = 0U; /* Signal to start from beginning of new sector */
		}
	}
}
